CREATE TABLE IF NOT EXISTS publishers (publisher_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_account_id uuid NOT NULL REFERENCES accounts(account_id), namespace text NOT NULL UNIQUE, status text NOT NULL CHECK (status IN ('active','suspended','revoked')), authority_revision bigint NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS publisher_members (publisher_id uuid NOT NULL REFERENCES publishers(publisher_id), account_id uuid NOT NULL REFERENCES accounts(account_id), role text NOT NULL CHECK (role IN ('publisher','reviewer','administrator')), status text NOT NULL CHECK (status IN ('active','suspended','revoked')), PRIMARY KEY (publisher_id, account_id));
CREATE TABLE IF NOT EXISTS packages (package_id text PRIMARY KEY, publisher_id uuid NOT NULL REFERENCES publishers(publisher_id), name text NOT NULL);
CREATE TABLE IF NOT EXISTS package_versions (package_id text NOT NULL REFERENCES packages(package_id), version text NOT NULL, manifest_json jsonb NOT NULL, manifest_digest text NOT NULL, state text NOT NULL CHECK (state IN ('staged','submitted','approved','published','revoked')), PRIMARY KEY (package_id, version));
CREATE TABLE IF NOT EXISTS package_artifacts (artifact_digest text PRIMARY KEY CHECK (artifact_digest ~ '^sha256-[0-9a-f]{64}$'), package_id text NOT NULL, version text NOT NULL, archive_digest text NOT NULL, size_bytes bigint NOT NULL CHECK (size_bytes >= 0), object_key text NOT NULL UNIQUE, state text NOT NULL CHECK (state IN ('staged','authoritative','revoked')), FOREIGN KEY (package_id, version) REFERENCES package_versions(package_id, version));
CREATE TABLE IF NOT EXISTS package_submissions (submission_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), publisher_id uuid NOT NULL REFERENCES publishers(publisher_id), package_id text NOT NULL, version text NOT NULL, artifact_digest text NOT NULL REFERENCES package_artifacts(artifact_digest), manifest_digest text NOT NULL, idempotency_key text NOT NULL, state text NOT NULL CHECK (state IN ('pending','approved','rejected')), UNIQUE (publisher_id,idempotency_key), FOREIGN KEY (package_id,version) REFERENCES package_versions(package_id,version));
CREATE TABLE IF NOT EXISTS package_reviews (review_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL UNIQUE REFERENCES package_submissions(submission_id), reviewer_account_id uuid NOT NULL REFERENCES accounts(account_id), decision text NOT NULL CHECK (decision IN ('approved','rejected')), artifact_digest text NOT NULL, reason text);
CREATE TABLE IF NOT EXISTS catalog_publications (publication_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), revision bigint NOT NULL UNIQUE, signer_key_id text, signature text, canonical_digest text, state text NOT NULL CHECK (state IN ('prepared','published','failed')));
CREATE TABLE IF NOT EXISTS catalog_entries (package_id text NOT NULL, version text NOT NULL, artifact_digest text NOT NULL REFERENCES package_artifacts(artifact_digest), publication_id uuid NOT NULL REFERENCES catalog_publications(publication_id), offer_json jsonb, state text NOT NULL CHECK (state IN ('published','revoked')), PRIMARY KEY (package_id,version));
CREATE TABLE IF NOT EXISTS orders (order_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES accounts(account_id), package_id text NOT NULL, version text NOT NULL, amount_minor bigint NOT NULL CHECK (amount_minor>=0), currency char(3) NOT NULL, state text NOT NULL CHECK (state IN ('created','checkout_pending','paid','refunded','failed')), idempotency_key text NOT NULL, UNIQUE(account_id,idempotency_key), FOREIGN KEY(package_id,version) REFERENCES catalog_entries(package_id,version));
CREATE TABLE IF NOT EXISTS payments (payment_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(order_id), provider text NOT NULL, provider_reference text UNIQUE, state text NOT NULL CHECK (state IN ('authorized','captured','failed','refunded')), amount_minor bigint NOT NULL, currency char(3) NOT NULL);
CREATE TABLE IF NOT EXISTS refunds (refund_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(order_id), provider_refund_id text UNIQUE, state text NOT NULL CHECK (state IN ('requested','confirmed','failed')), amount_minor bigint NOT NULL, reason text NOT NULL);
CREATE TABLE IF NOT EXISTS entitlements (entitlement_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES accounts(account_id), package_id text NOT NULL, version text NOT NULL, revision bigint NOT NULL DEFAULT 1, state text NOT NULL CHECK (state IN ('active','revoked','expired')), UNIQUE(account_id,package_id,version), FOREIGN KEY(package_id,version) REFERENCES catalog_entries(package_id,version));
CREATE TABLE IF NOT EXISTS outbox_events (outbox_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic text NOT NULL, aggregate_id text NOT NULL, payload_json jsonb NOT NULL, state text NOT NULL CHECK (state IN ('pending','leased','delivered','dead')), attempts integer NOT NULL DEFAULT 0, lease_until timestamptz);
CREATE TABLE IF NOT EXISTS reconciliation_runs (run_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, state text NOT NULL CHECK (state IN ('running','completed','mismatch','failed')));
CREATE TABLE IF NOT EXISTS recovery_jobs (recovery_job_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_type text NOT NULL, aggregate_id text NOT NULL, state text NOT NULL CHECK (state IN ('pending','leased','completed','dead')), attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, UNIQUE(job_type,aggregate_id));
CREATE TABLE IF NOT EXISTS release_signatures (signature_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artifact_digest text NOT NULL REFERENCES package_artifacts(artifact_digest), key_id text NOT NULL, algorithm text NOT NULL CHECK(algorithm='ed25519'), signature text NOT NULL, canonical_digest text NOT NULL, UNIQUE(artifact_digest,key_id));
REVOKE ALL ON publishers,publisher_members,packages,package_versions,package_artifacts,package_submissions,package_reviews,catalog_publications,catalog_entries,orders,payments,refunds,entitlements,outbox_events,reconciliation_runs,recovery_jobs,release_signatures FROM PUBLIC;
GRANT SELECT,INSERT,UPDATE ON publishers,publisher_members,packages,package_versions,package_artifacts,package_submissions,package_reviews,catalog_publications,catalog_entries,orders,payments,refunds,entitlements,reconciliation_runs,recovery_jobs TO tomni_runtime;
GRANT SELECT,INSERT ON outbox_events,release_signatures TO tomni_runtime;
GRANT SELECT ON publishers,publisher_members,packages,package_versions,package_artifacts,package_submissions,package_reviews,catalog_publications,catalog_entries,orders,payments,refunds,entitlements,outbox_events,reconciliation_runs,recovery_jobs,release_signatures TO tomni_backup;
